/* Modules (HMODULE): the translated program image, the translated DLL and
   the system DLLs that the runtime implements. */
#ifndef RT_MODULE_H
#define RT_MODULE_H

#include "rt.h"

#include <stdbool.h>

/* One export of a translated module (made by rt_modules_init from the
   export directory of the DLL file). */
typedef struct rt_export_entry {
    const char *name;
    uint32_t ordinal;
    char *addr; /* host address of the exported symbol */
} rt_export_entry;

/* One import that the runtime implements (generated by tools/gen_thunks.py).
   name is NULL for an import by ordinal. */
typedef struct rt_import_entry {
    const char *dll; /* lower case, without ".dll" */
    const char *name;
    uint32_t ordinal;
    char *addr;
} rt_import_entry;

extern const rt_import_entry rt_import_table[];
extern const unsigned rt_import_table_count;

/* The image symbols and entry points of the translated modules. */
extern char launcher_image[];
extern char engine_image[];
extern void engine_entry(void *cpu);
extern void launcher_entry(void *cpu);

/* The pointer initialization of the translated modules (llasm -ptrofs).
   Each module puts its initialize_pointers function at the start of this
   chain when the image loads; each function calls the previous one. The
   function writes each pointer of the module data as a guest address
   (host address minus ptrofs). It must run one time, after rt_mem_init
   and before guest code runs. */
extern void (*ptr_initialize_pointers)(uint64_t ptrofs);

/* Guest directory of the game (the directory of the program file). */
#define RT_GUEST_GAME_DIR "C:\\Prototype"
#define RT_GUEST_SYSTEM_DIR "C:\\Windows\\system32"

/* Make the module list. game_dir is the host directory that holds the
   game files; the export table of the translated DLL comes from the
   export directory of its file there. */
void rt_modules_init(const char *game_dir);

/* The program (exe) module handle. */
uint32_t rt_exe_module(void);

/* End the process (ExitProcess): DLL detach notifications, C runtime
   stream flush, then exit. Does not return. */
_Noreturn void rt_process_exit(uint32_t code);

/* C runtime work at process exit (rt_crt_file.c): flush all streams. */
void rt_crt_flush_all(void);

#endif
